mapper.select:
select ai.id as albumId, ai.album_title, ai.cover_url, ai.include_track_count, ai.is_finished, ai.status, ast.play_stat_num, ast.subscribe_stat_num, ast.buy_stat_num, ast.comment_stat_num from album_info ai left join (select s.album_id, SUM(IF(s.stat_type = '0401', s.stat_num, 0)) AS play_stat_num, SUM(IF(s.stat_type = '0402', s.stat_num, 0)) AS subscribe_stat_num, SUM(IF(s.stat_type = '0403', s.stat_num, 0)) AS buy_stat_num, SUM(IF(s.stat_type = '0404', s.stat_num, 0)) AS comment_stat_num FROM album_stat s where s.is_deleted = 0 GROUP BY s.album_id) ast on ai.id = ast.album_id
ai.is_deleted = 0
and ai.album_title like CONCAT('%', #{query.albumTitle}, '%')
and ai.status = #{query.status}
and ai.user_id = #{query.userId}
order by ai.create_time desc
